def transform(g):
    from collections import deque
    H,W=len(g),len(g[0])
    seen=set();comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                c=g[i][j];q=deque([(i,j)]);seen.add((i,j));cells=[]
                while q:
                    y,x=q.popleft();cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]==c:
                            seen.add((ny,nx));q.append((ny,nx))
                comps.append((c,cells))
    from collections import defaultdict
    pat=defaultdict(set)
    for c,cells in comps:
        s=tuple(sorted((y-min(p[0] for p in cells),x-min(p[1] for p in cells)) for y,x in cells))
        pat[s].add(c)
    out=[row[:] for row in g]
    for c,cells in comps:
        s=tuple(sorted((y-min(p[0] for p in cells),x-min(p[1] for p in cells)) for y,x in cells))
        if len(pat[s])>1:
            nc=max(pat[s])
            for y,x in cells: out[y][x]=nc
    return out
